#!/bin/bash
# E-0912-B (e): fresh v2 export gate + require over the RESTORED /workspace/shadow_bundle_v4 (read-only on the bundle; receipts only under root/e0912b). Env = r20 run_pod2_positive.sh [1]/[2] verbatim except V4CHAIN_DIR (= W3 device copy carrying the APPLIED contract 1188267a + on-disk v4_gate_common) and the receipt paths.
set -u; W=/workspace/w3_monthly_chain_2026-09-12; E=$W/root/e0912b; PY=/workspace/venv/bin/python; export OMP_NUM_THREADS=4 OPENBLAS_NUM_THREADS=4 MKL_NUM_THREADS=4
COMMON="BUNDLE_FEA=/workspace/data/wide_fea_v4.npy BUNDLE_META=/workspace/data/wide_fea_v4_meta.npz BUNDLE_BASE=/workspace/slow_scorer_v4base.json EXPORT_PANEL=/workspace/data/wide_panel_4h_v3splice.npz BUNDLE_CACHE=/workspace/data/dlnative_5m_wide829_f16_holefix2.npz FUND_AUG=/workspace/fund_aug.json.gz LIVE_PINS=/workspace/live_pins.json V4CHAIN_DIR=$W/device JUDGE_HC=/workspace/review_scratch/health_check SIGNAL_RECEIPT=/workspace/uplift_2026-09-11/infra2/GATE_signal_parity.json EXPORT_ARM=A1 BUNDLE_OUT=/workspace/shadow_bundle_v4"
echo "=== gate start $(date -u +%FT%TZ)"; sha256sum $W/device/v4e_gate_export_v2.py $W/device/v4_gate_common.py $W/device/ELIGIBILITY_CONTRACT.json | cut -c1-16,65-
env $COMMON EXPORT_GATE_OUT=$E/BUNDLE_export_v2_A1_restored2.json $PY $W/device/v4e_gate_export_v2.py > $E/gate_restored2.log 2>&1; rc=$?; echo "gate rc=$rc $(tail -1 $E/gate_restored.log | cut -c1-160)"
env $COMMON EXPORT_GATE_OUT=/dev/null REQUIRE_OUT=$E/REQUIRE_v2_A1_restored2.json $PY $W/device/v4e_gate_export_v2.py require $E/BUNDLE_export_v2_A1_restored2.json > $E/require_restored2.log 2>&1; rc2=$?; echo "require rc=$rc2 $(tail -1 $E/require_restored.log | cut -c1-160)"
nvidia-smi --query-gpu=utilization.gpu,memory.used --format=csv,noheader > $E/nvidia_after_gate.txt; echo "=== gate end $(date -u +%FT%TZ) rc=$rc require_rc=$rc2"; echo E0912B_GATE_DONE
